package com.alanbarber.app;
import android.app.*;
import android.os.*;
import android.net.Uri;
import android.content.*;
import android.graphics.Color;
import android.webkit.*;
import android.widget.*;
import android.view.*;
public class MainActivity extends Activity {
 private WebView web;private ProgressBar progress;private LinearLayout error;private String origin;
 @Override public void onCreate(Bundle state){super.onCreate(state);origin=getString(getResources().getIdentifier("app_origin","string",getPackageName()));getWindow().setStatusBarColor(Color.rgb(6,9,16));getWindow().setNavigationBarColor(Color.rgb(6,9,16));LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(6,9,16));root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);root.addView(progress,new LinearLayout.LayoutParams(-1,6));FrameLayout frame=new FrameLayout(this);root.addView(frame,new LinearLayout.LayoutParams(-1,0,1));web=new WebView(this);frame.addView(web);web.setBackgroundColor(Color.rgb(6,9,16));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSafeBrowsingEnabled(true);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setWebChromeClient(new WebChromeClient(){public void onProgressChanged(WebView v,int n){progress.setProgress(n);progress.setVisibility(n==100?View.GONE:View.VISIBLE);}});web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("https".equals(u.getScheme())&&Uri.parse(origin).getHost().equals(u.getHost())&&!u.getPath().endsWith(".apk"))return false;openExternal(u);return true;}public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())error.setVisibility(View.VISIBLE);}public void onPageFinished(WebView v,String u){CookieManager.getInstance().flush();}});web.setDownloadListener((u,a,c,m,l)->openExternal(Uri.parse(u)));error=new LinearLayout(this);error.setOrientation(LinearLayout.VERTICAL);error.setGravity(Gravity.CENTER);error.setPadding(40,40,40,40);error.setBackgroundColor(Color.rgb(6,9,16));TextView text=new TextView(this);text.setText("Sem conexão no momento.\nVerifique sua internet e tente novamente.");text.setTextColor(Color.WHITE);text.setTextSize(18);text.setGravity(Gravity.CENTER);error.addView(text);Button retry=new Button(this);retry.setText("Tentar novamente");retry.setOnClickListener(v->{error.setVisibility(View.GONE);web.loadUrl(origin+"/login.html");});error.addView(retry);frame.addView(error,new FrameLayout.LayoutParams(-1,-1));error.setVisibility(View.GONE);setContentView(root);web.loadUrl(origin+"/login.html");}
 private void openExternal(Uri u){String scheme=u.getScheme();if(!"https".equals(scheme)&&!"tel".equals(scheme)&&!"mailto".equals(scheme))return;try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(ActivityNotFoundException e){Toast.makeText(this,"Nenhum aplicativo disponível para abrir este link.",Toast.LENGTH_SHORT).show();}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){web.destroy();super.onDestroy();}
}
